\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{calc}
\pagestyle{empty}

%% ── IMF Institutional Palette ──
\definecolor{primary}{HTML}{002244}      % IMF deep navy
\definecolor{secondary}{HTML}{004080}    % IMF medium blue
\definecolor{accent}{HTML}{C8610A}       % Amber/burnt orange for risk warnings
\definecolor{accentlt}{HTML}{F5A623}     % Lighter amber
\definecolor{bgposter}{HTML}{F0F4F8}     % Cool light grey-blue background
\definecolor{redbg}{HTML}{FFF8F0}        % Warm amber tint for risk cards
\definecolor{bluebg}{HTML}{EEF3F9}       % Cool blue tint for data cards
\definecolor{darkbg}{HTML}{EDF1F6}       % Navy tint for policy cards
\definecolor{redtitlebg}{HTML}{FDEFD8}
\definecolor{bluetitlebg}{HTML}{D8E6F2}
\definecolor{darktitlebg}{HTML}{C8D6E5}
\definecolor{stathighlight}{HTML}{FFF3E0}
\definecolor{riskred}{HTML}{C0392B}
\definecolor{textdark}{HTML}{0D1B2A}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{gridline}{HTML}{B8C9DC}

\pagecolor{bgposter}
\color{textdark}

%% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{secondary}\rule[0.5ex]{6pt}{6pt}}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=0pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

%% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!16!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{66}{78}\selectfont\bfseries\color{white}%
    Global Economy in the Shadow of War}\\[8pt]
  {\fontsize{40}{50}\selectfont\bfseries\color{white!85}%
    IMF World Economic Outlook: Trends 2024--2026}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{white!65}%
    IMF-World Bank Annual Meetings Research Symposium
    $\;\boldsymbol{\cdot}\;$ April 2026}
}

%% ══════════════════════════════════════════════
%% STATS BANNER
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 3.0--3.3\%}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global growth band}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} 2024--2026 all editions}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent} $\mathbf{-0.8}$\%}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Below pre-pandemic avg}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} vs.\ historical $\sim$3.8\%}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary} 8}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} WEO editions reviewed}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Jul 2024 -- Apr 2026}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{30}{38}\selectfont\bfseries\color{accent} \textbf{ALL 8}}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} editions: risks tilted}\\[1pt]
      {\fontsize{22}{28}\selectfont\bfseries\color{accent} to the downside}\vspace{5pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════
%% COLUMN 1 — GROWTH TRAJECTORY (visual centrepiece)
%% ══════════════════════════════════════════════
\posterbox[bluecard, title={Growth Projections: The Narrow Band}
]{name=growth, column=1, between=row6 and row13}{
  \fontsize{30}{40}\selectfont

  {\fontsize{26}{34}\selectfont\color{textgray}\textit{%
    Global growth (8 WEO editions, Jul 2024--Apr 2026)}}

  \vspace{6pt}

  %% Hand-drawn timeline chart using TikZ
  \begin{tikzpicture}[x=0.93mm, y=26mm, font=\fontsize{22}{28}\selectfont]
    %% Grid lines
    \foreach \y/\label in {2.8/2.8\%, 3.0/3.0\%, 3.2/3.2\%, 3.4/3.4\%, 3.6/3.6\%, 3.8/3.8\%} {
      \draw[gridline, very thin] (0,\y-2.8) -- (175,\y-2.8);
      \node[left, color=textgray, font=\fontsize{20}{24}\selectfont] at (0,\y-2.8) {\label};
    }
    %% Pre-pandemic reference band
    \fill[primary!8] (0,1.0) rectangle (175,1.0);
    \draw[primary!40, dashed, thick] (0,1.0) -- (175,1.0)
      node[right, color=primary!60, font=\fontsize{19}{23}\selectfont] {pre-pandemic avg 3.8\%};
    %% Downside risk shading (below 3.3%)
    \fill[accent!10] (0,0) rectangle (175,0.5);
    %% 3.0–3.3 band shading
    \fill[secondary!12] (0,0.2) rectangle (175,0.5);
    %% Edition x-positions
    % 1=Jul24, 2=Oct24, 3=Jan25, 4=Apr25, 5=Jul25, 6=Oct25, 7=Jan26, 8=Apr26
    \def\xa{10}\def\xb{35}\def\xc{60}\def\xd{85}\def\xe{105}\def\xf{125}\def\xg{148}\def\xh{170}
    %% Growth 2024 line (Jul–Oct 2024)
    \draw[secondary, very thick] (\xa,0.4) -- (\xb,0.4);
    \foreach \x/\y in {\xa/0.4, \xb/0.4} {
      \fill[secondary] (\x,\y) circle (2.5pt);
    }
    %% Growth 2025 line
    \draw[primary, very thick]
      (\xa,0.5) -- (\xb,0.5) -- (\xc,0.5) -- (\xd,0.45) --
      (\xe,0.2) -- (\xf,0.22) -- (\xg,0.5) -- (\xh,0.4);
    \foreach \x/\y in {\xa/0.5, \xb/0.5, \xc/0.5, \xd/0.45, \xe/0.2, \xf/0.22, \xg/0.5, \xh/0.4} {
      \fill[primary] (\x,\y) circle (2.5pt);
    }
    %% Growth 2026 line (from Jan 2026)
    \draw[accent, very thick] (\xg,0.4) -- (\xh,0.35);
    \foreach \x/\y in {\xg/0.4, \xh/0.35} {
      \fill[accent] (\x,\y) circle (2.5pt);
    }
    %% X-axis labels
    \foreach \x/\lbl in {
      \xa/{Jul\\2024}, \xb/{Oct\\2024}, \xc/{Jan\\2025},
      \xd/{Apr\\2025}, \xe/{Jul\\2025}, \xf/{Oct\\2025},
      \xg/{Jan\\2026}, \xh/{Apr\\2026}
    } {
      \node[below, align=center, color=textgray,
            font=\fontsize{18}{22}\selectfont] at (\x, -0.05) {\lbl};
    }
    %% Axis
    \draw[textdark, thin] (0,-0.05) -- (175,-0.05);
    %% Legend
    \draw[primary, very thick] (0,-0.45) -- (18,-0.45);
    \fill[primary] (9,-0.45) circle (2pt);
    \node[right, color=primary, font=\fontsize{19}{23}\selectfont] at (19,-0.45) {2025 forecast};
    \draw[accent, very thick] (60,-0.45) -- (78,-0.45);
    \fill[accent] (69,-0.45) circle (2pt);
    \node[right, color=accent, font=\fontsize{19}{23}\selectfont] at (79,-0.45) {2026 forecast};
    \draw[secondary, very thick] (120,-0.45) -- (138,-0.45);
    \fill[secondary] (129,-0.45) circle (2pt);
    \node[right, color=secondary, font=\fontsize{19}{23}\selectfont] at (139,-0.45) {2024 forecast};
  \end{tikzpicture}

  \vspace{10pt}

  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\color{accent}%
    \textbf{Persistent mediocrity:} Growth locked in a 3.0--3.3\% band,
    \textbf{0.5--0.8 pp below} pre-pandemic historical average throughout.
  }}\vspace{4pt}

  \begin{itemize}
    \item Jul 2024 baseline: \textbf{3.2\%} for 2024; \textbf{3.3\%} for 2025
    \item Mid-2025 trough: \textbf{3.0\%}\ forecast for 2025 (Jul 2025 Update)
    \item Jan 2026 recovery: \textbf{3.3\%} (2025) $\to$ \textbf{3.2\%} (2027)
    \item Apr 2026: renewed downward pressure from geopolitical conflict
  \end{itemize}
}

%% ── Inflation & Monetary Policy ──
\posterbox[bluecard, title={Inflation \& Monetary Policy Pivot}
]{name=inflation, column=1, between=row13 and row20}{
  \fontsize{30}{40}\selectfont

  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont%
    \textbf{Oct 2024 ``Policy Pivot''}: Central banks began easing as global
    disinflation gained traction — but pace diverged sharply.
  }}\vspace{6pt}

  \begin{itemize}
    \item Global headline inflation: declining trajectory through 2026
    \item \textbf{US exception}: inflation returns to target \emph{more slowly} than peers
    \item Services inflation \textbf{sticky} — slows disinflation globally
    \item Apr 2026: \textbf{renewed pressure} from defense spending \& supply disruptions
  \end{itemize}

  \vspace{6pt}

  %% Inline schematic bar showing inflation trajectory
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{Relative inflation persistence (schematic):}}\\[4pt]
  \begin{tikzpicture}[font=\fontsize{22}{26}\selectfont]
    \def\bh{12pt}
    % Advanced Economies
    \node[left, color=textgray] at (0,0.5) {Adv.\ Econ.};
    \fill[secondary!70] (0.2,0.15) rectangle (5.0,0.55);
    \node[right, color=white, font=\fontsize{20}{24}\selectfont] at (0.3,0.35) {Faster to target};
    % US
    \node[left, color=textgray] at (0,-0.25) {United States};
    \fill[accent!80] (0.2,-0.55) rectangle (7.2,-0.15);
    \node[right, color=white, font=\fontsize{20}{24}\selectfont] at (0.3,-0.35) {Slower — services sticky};
    % EMDEs
    \node[left, color=textgray] at (0,-1.0) {EMDEs};
    \fill[secondary!45] (0.2,-1.35) rectangle (4.2,-0.95);
    \node[right, color=textdark, font=\fontsize{20}{24}\selectfont] at (4.4,-1.15) {Varied};
  \end{tikzpicture}

  \vspace{8pt}
  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{accent}%
    \textbf{Risk}: Premature easing could reignite inflation;
    late easing risks unnecessary recession.
  }}
}

%% ══════════════════════════════════════════════
%% COLUMN 2 — RISKS (dominant visual)
%% ══════════════════════════════════════════════
\posterbox[riskcard, title={Dominant Downside Risks}
]{name=risks, column=2, between=row6 and row13}{
  \fontsize{30}{40}\selectfont

  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \fontsize{32}{42}\selectfont\bfseries\color{accent}%
    $\boldsymbol{\Downarrow}$\ Risk balance \textbf{tilted to the downside}
    across \emph{all 8 WEO editions reviewed.}
  }}\vspace{8pt}

  %% Risk tiles
  \colorbox{riskred!12}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{riskred}%
      $\blacktriangleright$\ Trade Policy Escalation}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    Tariff wars \& retaliatory measures (2025+).
    Front-loading of activity temporarily \emph{masks} damage.}
  }}\vspace{5pt}

  \colorbox{riskred!12}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{riskred}%
      $\blacktriangleright$\ Geopolitical Tensions}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    Middle East conflict, broader security fractures.
    Apr 2026 titled \emph{"Shadow of War"}.}
  }}\vspace{5pt}

  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{accent}%
      $\blacktriangleright$\ Technology Re-evaluation}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    Correction risk if AI/tech investment expectations
    prove excessive.}
  }}\vspace{5pt}

  \colorbox{accent!15}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{accent}%
      $\blacktriangleright$\ Persistent Services Inflation}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    US inflation returns to target \emph{more slowly}.
    Complicates monetary pivot globally.}
  }}\vspace{5pt}

  %% Risk intensity chart (schematic)
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{Risk intensity by edition (schematic):}}\\[4pt]
  \begin{tikzpicture}[x=0.94mm, font=\fontsize{19}{23}\selectfont]
    \def\editions{{"Jul'24","Oct'24","Jan'25","Apr'25","Jul'25","Oct'25","Jan'26","Apr'26"}}
    \def\heights{12,14,15,20,22,19,18,28}
    \foreach \i/\h in {0/12,1/14,2/15,3/20,4/22,5/19,6/18,7/28} {
      \pgfmathsetmacro\xx{\i*21+2}
      \pgfmathsetmacro\col{int(\i*14+30)}
      \fill[accent!\col!riskred] (\xx pt,0) rectangle ++(16pt,\h pt);
    }
    \foreach \i/\lbl in {0/{Jul\\24},1/{Oct\\24},2/{Jan\\25},3/{Apr\\25},
                          4/{Jul\\25},5/{Oct\\25},6/{Jan\\26},7/{Apr\\26}} {
      \pgfmathsetmacro\xx{\i*21+10}
      \node[below, align=center, color=textgray] at (\xx pt, -2pt) {\lbl};
    }
    \draw[textdark, thin] (0,0) -- (175pt,0);
    \node[above right, color=accent, font=\fontsize{18}{22}\selectfont] at (145pt,26pt) {\textbf{Apr'26}};
  \end{tikzpicture}
}

%% ── WEO Edition Quick Reference ──
\posterbox[darkcard, title={WEO Edition Quick Reference}
]{name=editions, column=2, between=row13 and row17}{
  \fontsize{27}{36}\selectfont
  \renewcommand{\arraystretch}{1.55}
  \begin{tabular}{@{}p{0.26\linewidth}p{0.65\linewidth}@{}}
    \rowcolor{primary!12}
    \textbf{Edition} & \textbf{Headline Theme} \\
    Jul 2024 & Sticky Spot — inflation stubborn \\
    \rowcolor{primary!8}
    Oct 2024 & Policy Pivot — easing begins \\
    Jan 2025 & Divergent \& Uncertain \\
    \rowcolor{primary!8}
    Apr 2025 & Critical Juncture \\
    Jul 2025 & Tenuous Resilience \\
    \rowcolor{primary!8}
    Oct 2025 & Flux, Prospects Dim \\
