    \rowcolor{primary!14}
    \textbf{Period} & \textbf{Primary Focus} \\
    Mid-2024 & Disinflation; begin easing carefully \\
    \rowcolor{primary!8}
    Late 2024 & Pivot policy; fiscal sustainability \\
    Early 2025 & Rebuild buffers; demographics, gender \\
    \rowcolor{primary!8}
    Mid-2025 & Restore confidence; tariff uncertainty \\
    Late 2025 & Strengthen frameworks; industrial policy \\
    \rowcolor{accent!14}
    Early 2026 & \textbf{\color{accent}Agile; defense trade-offs; recovery} \\
  \end{tabular}}
}

%% ── Special Analytical Themes ──
\posterbox[bluecard, title={Special Analytical Themes}
]{name=themes, column=3, between=row14 and row18}{
  \fontsize{30}{40}\selectfont

  {\fontsize{26}{34}\selectfont\color{textgray}\textit{%
    Deep-dive chapters reflect IMF's broadening analytical lens:}}

  \vspace{6pt}
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Monetary policy} in global disinflation
    \item \textbf{Industrial policy} — effectiveness \& fiscal cost
    \item Social acceptability of \textbf{structural reforms}
    \item \textbf{Aging populations} \& demographic headwinds
    \item Gender disparities \& \textbf{migrant skill alignment}
  \end{itemize}

  \vspace{6pt}
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \fontsize{27}{35}\selectfont%
    Themes signal a shift: IMF broadening beyond macro stabilization
    toward \textbf{inclusive and sustainable growth}.
  }}
}

%% ── Data Sources ──
\posterbox[darkcard, title={Data \& Methodology}
]{name=sources, column=3, between=row18 and row20}{
  \fontsize{27}{36}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item IMF World Economic Outlook (8 editions: Jul 2024 -- Apr 2026)
    \item WEO Updates (Jan, Jul) + Full reports (Apr, Oct)
    \item Projections as published; no ex-post revisions applied
    \item Risk assessments based on IMF balance-of-risks narratives
  \end{itemize}
  \vspace{4pt}
  {\fontsize{23}{30}\selectfont\color{textgray}%
    Analysis: IMF-World Bank Research Symposium, April 2026.
    All growth figures in percent change of real GDP.}
}

\end{tcbposter}
\end{document}

