%% ── INFLATION ──
\posterbox[bluecard, title={Inflation \& Monetary Policy Pivot}
]{name=inflation, column=1, between=row13 and row20}{
  \fontsize{30}{40}\selectfont

  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont%
    \textbf{Oct 2024 ``Policy Pivot''}: Central banks began easing as
    global disinflation gained traction --- but the path diverged sharply.
  }}\vspace{6pt}

  \begin{itemize}
    \item Global headline inflation: declining trajectory through 2026
    \item \textbf{US exception}: returns to target \emph{more slowly} than peers
    \item Services inflation \textbf{sticky} --- primary drag on disinflation
    \item Apr 2026: \textbf{renewed pressures} from defense spending \& supply shocks
  \end{itemize}

  \vspace{6pt}
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{Relative inflation persistence (schematic):}}\\[6pt]
  \renewcommand{\arraystretch}{1.8}
