  \begin{tabular}{@{}p{0.32\linewidth}p{0.58\linewidth}@{}}
    Advanced Econ. &
      \colorbox{secondary!60}{\rule{0pt}{9pt}\rule{100pt}{0pt}}\ faster \\
    \rowcolor{accent!12}
    United States &
      \colorbox{accent!80}{\rule{0pt}{9pt}\rule{148pt}{0pt}}\ \textbf{sticky} \\
    EMDEs &
      \colorbox{secondary!40}{\rule{0pt}{9pt}\rule{80pt}{0pt}}\ varied \\
  \end{tabular}}

  \vspace{8pt}
  \colorbox{accent!16}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{accent}%
    \textbf{Risk}: Premature easing reignites inflation;
    late easing triggers unnecessary recession.
  }}
}

