\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{array}
\usepackage{booktabs}
\pagestyle{empty}

%% ── IMF Institutional Palette ──
\definecolor{primary}{HTML}{002244}
\definecolor{secondary}{HTML}{004080}
\definecolor{accent}{HTML}{C8610A}
\definecolor{bgposter}{HTML}{EEF2F7}
\definecolor{redbg}{HTML}{FFF8F0}
\definecolor{bluebg}{HTML}{EEF3F9}
\definecolor{darkbg}{HTML}{EDF1F6}
\definecolor{redtitlebg}{HTML}{FDEFD8}
\definecolor{bluetitlebg}{HTML}{D8E6F2}
\definecolor{darktitlebg}{HTML}{C8D6E5}
\definecolor{stathighlight}{HTML}{FFF3E0}
\definecolor{riskred}{HTML}{9B1C1C}
\definecolor{textdark}{HTML}{0D1B2A}
\definecolor{textgray}{HTML}{4A5568}
\definecolor{gridline}{HTML}{B8C9DC}
\definecolor{growthband}{HTML}{D4E3F2}

\pagecolor{bgposter}
\color{textdark}

%% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{secondary}\rule[0.5ex]{6pt}{6pt}}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=0pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

%% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluetitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!16!bgposter,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{38}{46}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

%% ── Bar helper (pure LaTeX, no TikZ) ──
\newcommand{\barrow}[3]{%
  % #1=label #2=width fraction*100 #3=colour
  {\fontsize{25}{30}\selectfont\color{textgray}#1}\hfill
  \colorbox{#3}{\rule{0pt}{10pt}\rule{#2pt}{0pt}}\par\vspace{3pt}%
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

%% ══════════════════════════════════════════════
%% TITLE BAR
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{64}{76}\selectfont\bfseries\color{white}%
    Global Economy in the Shadow of War}\\[8pt]
  {\fontsize{38}{48}\selectfont\bfseries\color{white!82}%
    IMF World Economic Outlook: Trends 2024--2026}\\[10pt]
  {\fontsize{28}{36}\selectfont\color{white!62}%
    IMF--World Bank Annual Meetings Research Symposium
    $\;\boldsymbol{\cdot}\;$ April 2026}
}

%% ══════════════════════════════════════════════
%% STATS BANNER
%% ══════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!10!bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 3.0--3.3\%}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Global growth band}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} across all 8 editions}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!60}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} $-$0.8\,pp}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} Below pre-pandemic avg}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} vs.\ historical $\sim$3.8\%}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{secondary!50}{bluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{primary} 8}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} WEO editions reviewed}\\[1pt]
      {\fontsize{20}{26}\selectfont\color{textgray} Jul 2024 -- Apr 2026}\vspace{5pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.24\linewidth}\centering
    \fcolorbox{accent!70}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{32}{40}\selectfont\bfseries\color{accent} ALL 8}\\[2pt]
      {\fontsize{24}{30}\selectfont\color{textdark} editions: risks tilted}\\[1pt]
      {\fontsize{24}{30}\selectfont\bfseries\color{accent} to the downside}\vspace{5pt}%
    }}
  \end{minipage}
}

%% ══════════════════════════════════════════════
%% COL 1 — GROWTH TRAJECTORY (visual centrepiece)
%% ══════════════════════════════════════════════
\posterbox[bluecard, title={Growth Projections: The Narrow Band}
]{name=growth, column=1, between=row6 and row13}{
  \fontsize{30}{40}\selectfont

  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \fontsize{30}{40}\selectfont\color{accent}%
    \textbf{Persistent mediocrity:} locked in a 3.0--3.3\% band,
    \textbf{0.5--0.8\,pp below} the pre-pandemic historical average.
  }}\vspace{8pt}

  %% Dot-plot table: each edition on a row, bar shows forecast value
  {\fontsize{26}{34}\selectfont\color{textgray}\textit{%
    Global growth forecasts per WEO edition}}\\[6pt]

  \renewcommand{\arraystretch}{1.7}
  {\fontsize{26}{34}\selectfont
  \begin{tabular}{@{}p{0.34\linewidth}p{0.10\linewidth}p{0.46\linewidth}@{}}
    \rowcolor{primary!12}
    \textbf{Edition} & \textbf{Year} & \textbf{Forecast (real GDP \%)} \\
    Jul 2024 & 2024 &
      \colorbox{secondary!55}{\rule{0pt}{9pt}\rule{96pt}{0pt}}\ \ 3.2\% \\
    \rowcolor{primary!6}
    Oct 2024 & 2025 &
      \colorbox{secondary!55}{\rule{0pt}{9pt}\rule{96pt}{0pt}}\ \ $\sim$3.3\% \\
    Jan 2025 & 2025 &
      \colorbox{secondary!60}{\rule{0pt}{9pt}\rule{96pt}{0pt}}\ \ 3.3\% \\
    \rowcolor{primary!6}
    Apr 2025 & 2025 &
      \colorbox{accent!50}{\rule{0pt}{9pt}\rule{76pt}{0pt}}\ \ $\downarrow$ \\
    Jul 2025 & 2025 &
      \colorbox{accent!70}{\rule{0pt}{9pt}\rule{60pt}{0pt}}\ \ \textbf{3.0\%} \\
    \rowcolor{primary!6}
    Oct 2025 & 2025 &
      \colorbox{accent!55}{\rule{0pt}{9pt}\rule{70pt}{0pt}}\ \ $\downarrow$ \\
    Jan 2026 & 2026 &
      \colorbox{secondary!55}{\rule{0pt}{9pt}\rule{96pt}{0pt}}\ \ 3.3\% \\
    \rowcolor{accent!14}
    \textbf{Apr 2026} & 2026 &
      \colorbox{accent!80}{\rule{0pt}{9pt}\rule{60pt}{0pt}}\ \ \textbf{\color{accent}renewed pressure} \\
  \end{tabular}}

  \vspace{8pt}
  \begin{itemize}
    \item Growth floor: \textbf{3.0\%} (Jul 2025); ceiling: \textbf{3.3\%}
    \item Jan 2026 moment of stability: 3.3\% (2025), 3.2\% (2026--27)
    \item Apr 2026: war-linked pressure reverses stabilisation
    \item Structural gap vs.\ 2010s average \textbf{persists}
  \end{itemize}
}

%% ── INFLATION ──
\posterbox[bluecard, title={Inflation \& Monetary Policy Pivot}
]{name=inflation, column=1, between=row13 and row20}{
  \fontsize{30}{40}\selectfont

  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \fontsize{29}{38}\selectfont%
    \textbf{Oct 2024 ``Policy Pivot''}: Central banks began easing as
    global disinflation gained traction --- but the path diverged sharply.
  }}\vspace{6pt}

  \begin{itemize}
    \item Global headline inflation: declining trajectory through 2026
    \item \textbf{US exception}: returns to target \emph{more slowly} than peers
    \item Services inflation \textbf{sticky} --- primary drag on disinflation
    \item Apr 2026: \textbf{renewed pressures} from defense spending \& supply shocks
  \end{itemize}

  \vspace{6pt}
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{Relative inflation persistence (schematic):}}\\[6pt]
  \renewcommand{\arraystretch}{1.8}
  {\fontsize{26}{34}\selectfont
  \begin{tabular}{@{}p{0.32\linewidth}p{0.58\linewidth}@{}}
    Advanced Econ. &
      \colorbox{secondary!60}{\rule{0pt}{9pt}\rule{100pt}{0pt}}\ faster \\
    \rowcolor{accent!12}
    United States &
      \colorbox{accent!80}{\rule{0pt}{9pt}\rule{148pt}{0pt}}\ \textbf{sticky} \\
    EMDEs &
      \colorbox{secondary!40}{\rule{0pt}{9pt}\rule{80pt}{0pt}}\ varied \\
  \end{tabular}}

  \vspace{8pt}
  \colorbox{accent!16}{\parbox{0.94\linewidth}{%
    \fontsize{28}{36}\selectfont\color{accent}%
    \textbf{Risk}: Premature easing reignites inflation;
    late easing triggers unnecessary recession.
  }}
}

%% ══════════════════════════════════════════════
%% COL 2 — DOWNSIDE RISKS
%% ══════════════════════════════════════════════
\posterbox[riskcard, title={Dominant Downside Risks}
]{name=risks, column=2, between=row6 and row13}{
  \fontsize{30}{40}\selectfont

  \colorbox{accent!22}{\parbox{0.94\linewidth}{%
    \fontsize{32}{42}\selectfont\bfseries\color{accent}%
    $\Downarrow$ Risk balance \textbf{tilted to the downside}
    across \emph{all 8 WEO editions}.
  }}\vspace{8pt}

  \colorbox{riskred!14}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{riskred}%
      $\blacktriangleright$ Trade Policy Escalation}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    Tariff wars \& retaliatory measures (2025+).
    Front-loading temporarily \emph{masks} underlying damage.}
  }}\vspace{5pt}

  \colorbox{riskred!14}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{riskred}%
      $\blacktriangleright$ Geopolitical Tensions}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    Middle East conflict, broader security fractures.
    Apr 2026 titled \emph{``Shadow of War''}.}
  }}\vspace{5pt}

  \colorbox{accent!16}{\parbox{0.94\linewidth}{%
    {\fontsize{30}{38}\selectfont\bfseries\color{accent}%
      $\blacktriangleright$ Technology Re-evaluation}\\[2pt]
    {\fontsize{27}{35}\selectfont%
    AI/tech investment expectations may prove excessive;
